    @api_version_check(min_version=109)
    async def rapi_orgstructure_admin_unit_create(
        self,
        name: str,
        _type: Literal["organization", "department"],
        domains: list[str],
        parentId: Optional[str] = None,
        orgstructureId: Optional[str] = None,
        description: Optional[str] = "Default description",
        logo: Optional[str] = None,
        lead: Optional[str] = None,
    ):
        """
        Создание оргединицы
        :param unitId: идентификатор оргединицы
        :param name: Название оргединицы
        :param type: тип создаваемое оргединицы ([ organization, department ])
        :param domains: Список доменов закрепленных за ОЕ
        :param parentId: идентификатор родительское оргдеиницы
        :param orgstructureId: Идентификатор оргструктуры. Если опущен, то оргструктура по умолчанию
        :param description: описание создаваемой оргединицы
        :param logo: идентификатор логотипа
        :param lead: email пользователя
        :param requester: идентификатор отправителя запроса
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/orgstructure/admin/unit/create",
            json={
                "authToken": self.org_struct_admin_token,
                "reqId": self.getReqId(),
                "params": {
                    "name": name,
                    "parentId": parentId or "",
                    "type": _type,
                    "orgstructureId": orgstructureId,
                    "description": description,
                    "logo": logo,
                    "lead": lead,
                    "domains": domains,
                    "requester": self.uin,
                },
            },
        )

