    @api_version_check(min_version=109)
    async def rapi_orgstructure_get_root(self, orgstructureId: Optional[str] = None):
        """
        Просмотр корня оргструктуры
        Посмотреть корня оргструктуры: головная организация и ее дети
        :param orgstructureId: Идентификатор оргструктуры. Если опущен, то оргструктура по умолccccbcbчанию
        :return: тело ответа сервера
        """
        params = {}

        if orgstructureId is not None:
            params["orgstructureId"] = orgstructureId

        return await self.post(
            "rapi/orgstructure/get/root",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": params,
            },
        )

